drop function if exists public.niche_page_listings(text);
create or replace function public.niche_page_stats(p_niche text) returns table ( listings bigint, dr_min integer, dr_max integer, countries bigint, starting_price_minor integer ) language sql stable security definer set search_path = public as $$ with matched as ( select m.id, m.domain_rating, m.country, ( select coalesce( min(s.price_minor) filter (where s.available), min(s.price_minor) ) from public.services s where s.website_id = m.id ) as lowest_price_minor from public.marketplace_listings m where m.status = 'active' and (m.niche = p_niche or p_niche = any(m.secondary_niches)) ) select count(*), coalesce(min(domain_rating) filter (where domain_rating > 0), 0)::integer, coalesce(max(domain_rating) filter (where domain_rating > 0), 0)::integer, count(distinct country) filter (where country is not null), (min(lowest_price_minor) filter (where lowest_price_minor > 0))::integer from matched; $$;
comment on function public.niche_page_stats(text) is 'The band at the top of /guest-posts/<niche>: how many listings, the domain rating range, how many countries, and the lowest price. Replaces shipping every listing in the niche to count them.';
create or replace function public.niche_page_samples( p_niche text, p_count integer, p_min_traffic integer ) returns table ( domain_rating integer, organic_traffic integer, country text, lowest_price_minor integer ) language sql stable security definer set search_path = public as $$ with eligible as ( select m.domain_rating, m.organic_traffic, m.country, ( select coalesce( min(s.price_minor) filter (where s.available), min(s.price_minor) ) from public.services s where s.website_id = m.id ) as lowest_price_minor, m.id from public.marketplace_listings m where m.status = 'active' and (m.niche = p_niche or p_niche = any(m.secondary_niches)) ), worth_showing as ( select * from eligible where organic_traffic >= p_min_traffic and lowest_price_minor > 0 ), ordered as ( select w.*, row_number() over (order by w.domain_rating desc, w.id asc) - 1 as pos, count(*) over () as total from worth_showing w ) select o.domain_rating, o.organic_traffic, o.country, o.lowest_price_minor from ordered o where o.total <= greatest(p_count, 1) or p_count <= 1 and o.pos = 0 or o.pos in ( select round(i * (o.total - 1)::numeric / (p_count - 1))::bigint from generate_series(0, p_count - 1) as i ) order by o.pos; $$;
comment on function public.niche_page_samples(text, integer, integer) is 'A spread of a niche''s listings for the sample table on /guest-posts/<niche>, walking the same strides as spread() in niche-landing.ts. Takes the count and the traffic floor as parameters so those constants keep one copy, in TypeScript.';
revoke all on function public.niche_page_stats(text) from public, anon, authenticated;
grant execute on function public.niche_page_stats(text) to service_role;
revoke all on function public.niche_page_samples(text, integer, integer) from public, anon, authenticated;
grant execute on function public.niche_page_samples(text, integer, integer) to service_role;
